import unittest

class Tests(unittest.TestCase):
    def test_values(self):
        for actual, expected in [(2, 2), (3, 3)]:
            with self.subTest(actual=actual):
                self.assertEqual(actual, expected)

import pytest

@pytest.mark.parametrize('value, expected', [(2, 4), (3, 6)])
def test_double(value, expected):
    assert value * 2 == expected

def test_join_items():
    result = []
    for value in (1, 2, 3):
        result.append(str(value))
    assert result == ['1', '2', '3']

class TestGrid:
    def test_cells_match(self):
        expected = [[1, 2], [3, 4]]
        actual = [[1, 2], [3, 4]]
        for row_index, row in enumerate(actual):
            for column_index, value in enumerate(row):
                self.assertEqual(value, expected[row_index][column_index])

import pytest

def test_each_bad_value_is_rejected():
    for value in ('', None, 'x' * 100):
        with pytest.raises(ValueError):
            validate(value)

def test_poll_eventually_returns_ready():
    attempts = 0
    while attempts < 3:
        attempts += 1
        assert poll(attempts) is not None

def test_optional_feature(config):
    if not config.enabled:
        assert config.result is None
        return
    assert config.result is not None

def test_parsed_result():
    def assert_valid(result):
        if result.ok:
            assert result.value
        else:
            assert result.error
    assert_valid(parse('input'))

def test_state_is_supported(state):
    if state.is_supported:
        assert state.name

def test_outcome_depends_on_input(request):
    if request.is_valid:
        assert request.result == 'accepted'
    else:
        assert request.result == 'rejected'

def test_validation_response(response):
    if response.valid:
        if response.complete:
            assert response.message == 'ok'
        else:
            assert response.message == 'incomplete'
    else:
        assert response.message == 'invalid'
